INSERT INTO public."reports" SELECT * FROM json_populate_recordset(NULL::public."reports", $_replit_snapshot_$[{"id":21,"project_id":6,"type":"monthly","report_date":"2025-07-31","period_start":"2025-07-01","period_end":"2025-07-31","work_description":"- إنجاز الهيكل الخرساني للعمارة A حتى الطابق الثامن\n- إنجاز الهيكل الخرساني للعمارة B حتى الطابق السادس\n- إنجاز الهيكل الخرساني للعمارة C حتى الطابق الثالث\n- بدء أعمال الهيكل الخرساني للعمارة D\n- تركيب 180 طن حديد تسليح و صب 2,100 م³ خرسانة\n- تقدم أعمال البناء بالطوب للعمارة A (60%)\n- بدء التمديدات الكهربائية للأدوار السفلية العمارة A\n- بدء أعمال اللياسة الخارجية للعمارة A (الأدوار 1-3)","progress_percentage":22,"technical_notes":"- تسجيل حادثة عمل بسيطة (سقوط عامل من ارتفاع 1.5م) تم التعامل معها\n- نقص في عمالة الحدادة المسلحة أثّر على سرعة التقدم\n- تم اعتماد عينات الدهانات والسيراميك من المالك","recommendations":"- استقدام فريق حدادة إضافي (15 عامل) لتسريع الإنجاز\n- تكثيف إجراءات السلامة خاصة العمل على الارتفاعات\n- تأمين مواد التشطيبات مبكراً لتجنب التأخير","image_urls":[],"created_by_id":1,"created_at":"2026-04-06T08:52:37.470254+00:00","updated_at":"2026-04-06T08:52:37.470254+00:00","report_number":5,"activities_snapshot":null,"image_groups":null,"status":"approved","approved_at":null,"approved_by_id":null},{"id":17,"project_id":6,"type":"weekly","report_date":"2025-02-10","period_start":"2025-02-03","period_end":"2025-02-09","work_description":"- إنجاز أعمال الحفر للعمارة A بعمق 4.5 متر وتسوية القاعدة\n- بدء أعمال حفر العمارة B\n- نقل 1,200 متر مكعب من الأتربة خارج الموقع\n- تركيب شبكة صرف مياه الأمطار المؤقتة\n- استلام حديد التسليح للأساسات (الدفعة الأولى 120 طن)","progress_percentage":3,"technical_notes":"- تم العثور على طبقة صخرية على عمق 3.8 متر في الجزء الشرقي من العمارة A مما تطلب استخدام كسارة هيدروليكية\n- تأخر وصول حفارة CAT 320 بسبب أعطال ميكانيكية ليومين","recommendations":"- يجب تكثيف العمالة في أعمال الحفر لتعويض التأخر\n- إجراء اختبارات تربة إضافية في موقع العمارة C","image_urls":["/api/uploads/1775466015265-882823476.jpg","/api/uploads/1775466017547-906269988.png","/api/uploads/1775466019588-811298105.png","/api/uploads/1775466021127-645513357.png","/api/uploads/1775466022674-264222880.png"],"created_by_id":1,"created_at":"2026-04-06T08:52:22.589663+00:00","updated_at":"2026-04-06T09:00:25.497+00:00","report_number":1,"activities_snapshot":null,"image_groups":null,"status":"approved","approved_at":null,"approved_by_id":null},{"id":27,"project_id":6,"type":"weekly","report_date":"2026-03-16","period_start":"2026-03-09","period_end":"2026-03-15","work_description":"- استمرار أعمال التشطيبات العمارة A على جميع الأدوار\n- تركيب الأبواب الخشبية للأدوار 1-4 العمارة A (64 باب)\n- بدء تركيب خطوط التكييف المركزي العمارة A\n- أعمال اللياسة الداخلية العمارة B (بدء)\n- صب الطابق الأخير العمارة C","progress_percentage":35,"technical_notes":"- تأخر مقاول الباطن للدهانات عن الجدول المتفق عليه\n- حالة الطقس جيدة ومناسبة للعمل","recommendations":"- إنذار مقاول الدهانات وتحديد مهلة نهائية\n- تجهيز خطة عمل مكثفة للشهرين القادمين","image_urls":[],"created_by_id":1,"created_at":"2026-04-06T08:52:59.750438+00:00","updated_at":"2026-04-06T08:52:59.750438+00:00","report_number":11,"activities_snapshot":null,"image_groups":null,"status":"approved","approved_at":null,"approved_by_id":null},{"id":32,"project_id":6,"type":"weekly","report_date":"2026-04-06","period_start":"2026-04-06","period_end":"2026-04-13","work_description":"قففففف","progress_percentage":44,"technical_notes":"فففففففففففف","recommendations":"ففففففف","image_urls":["/api/uploads/1775497368925-634214152.jpg","/api/uploads/1775497369248-336138175.jpg","/api/uploads/1775497369401-70296514.png","/api/uploads/1775497369714-10262879.jpg","/api/uploads/1775497370480-547234609.jpg"],"created_by_id":3,"created_at":"2026-04-06T17:42:55.448371+00:00","updated_at":"2026-04-06T17:42:55.448371+00:00","report_number":13,"activities_snapshot":null,"image_groups":null,"status":"approved","approved_at":null,"approved_by_id":null},{"id":18,"project_id":6,"type":"weekly","report_date":"2025-03-17","period_start":"2025-03-10","period_end":"2025-03-16","work_description":"- صب خرسانة الأساسات للعمارة A (القواعد المنفصلة والشدادات) - 380 م³\n- تركيب حديد تسليح أساسات العمارة B\n- إنجاز أعمال الردم الهيكلي للعمارة A بنسبة 60%\n- بدء أعمال العزل المائي تحت الأساسات باستخدام مادة البيتومين\n- صب خرسانة نظافة للعمارة C","progress_percentage":8,"technical_notes":"- نتائج اختبارات ضغط الخرسانة بعد 7 أيام: 28 نيوتن/مم² (مطابقة للمواصفات)\n- تم رصد تسرب مياه جوفية في حفرة العمارة B واستخدام مضخات لنزح المياه","recommendations":"- تأمين مضخات إضافية للتعامل مع المياه الجوفية\n- مراجعة تصميم الأساسات للعمارة B مع المكتب الاستشاري بسبب ارتفاع منسوب المياه","image_urls":[],"created_by_id":1,"created_at":"2026-04-06T08:52:26.44475+00:00","updated_at":"2026-04-06T08:52:26.44475+00:00","report_number":2,"activities_snapshot":null,"image_groups":null,"status":"approved","approved_at":null,"approved_by_id":null},{"id":19,"project_id":6,"type":"monthly","report_date":"2025-04-30","period_start":"2025-04-01","period_end":"2025-04-30","work_description":"- إنجاز كامل الأساسات للعمارات A و B و C\n- بدء أعمال الهيكل الخرساني للعمارة A (إنجاز الطابق الأرضي والأول)\n- صب 1,850 متر مكعب خرسانة خلال الشهر\n- تركيب 245 طن حديد تسليح\n- إنجاز أعمال العزل المائي لجميع الأساسات المنفذة\n- بدء حفر أساسات العمارة D\n- تركيب رافعتين برجيتين (Tower Crane) في الموقع\n- بدء أعمال التمديدات الكهربائية المدفونة تحت الأساسات","progress_percentage":14,"technical_notes":"- وصول شحنة الخرسانة الجاهزة من مصنع الشركة العربية للخرسانة بانتظام\n- تحقيق نسبة سلامة 100% خلال الشهر بدون حوادث\n- درجات الحرارة مناسبة لأعمال الصب\n- تمت معالجة مشكلة المياه الجوفية في العمارة B باستخدام نظام نزح دائم","recommendations":"- زيادة فريق النجارة المسلحة لتسريع أعمال الشدات الخشبية\n- طلب الدفعة الثالثة من حديد التسليح (200 طن)\n- تنسيق مع بلدية مصراتة لتوصيل الكهرباء المؤقتة بقدرة أعلى","image_urls":[],"created_by_id":1,"created_at":"2026-04-06T